import{_ as s,C as a,o,c as i,E as t,a2 as c}from"./chunks/framework.VWKgVqrc.js";const y=JSON.parse('{"title":"The Same Workflow Results Can Produce Different Rankings","description":"","frontmatter":{"title":"The Same Workflow Results Can Produce Different Rankings","article_type":"experiment-report","edition":"research-center","research_question":"部分得分、完整验收与领域权重如何改变同一批工作流结果的比较？","summary":"Across 25 released configurations, partial score and complete acceptance reverse 34 pairwise orderings robustly to rounding. Domain weighting reverses six more, only three beyond rounding uncertainty. State the success objective before interpreting the ranking.","research_question_en":"How do partial scores, complete acceptance and domain weights change comparisons of the same workflow results?","sources":["https://arxiv.org/html/2611.12856v1","https://github.com/Einsia/WorkflowArena/tree/637adecbe59ced8780279301de22b0f582495dea"],"date":"2026-11-11","column":"industry-architecture","category":"daily","pageClass":"runtime-v6-article","item_id":"SIG-20261111-007","lifecycle":"Published","cover":"/assets/covers/daily-2026-11-11-sig-20261111-007-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/industry/2026-11-11-sig-20261111-007.md","filePath":"en/industry/2026-11-11-sig-20261111-007.md","lastUpdated":null}'),l={name:"en/industry/2026-11-11-sig-20261111-007.md"};function d(h,e,p,u,g,m){const r=a("ArticleCover"),n=a("ArticleTableScroll");return o(),i("div",null,[t(r,{image:"/assets/covers/daily-2026-11-11-sig-20261111-007-cover.png",kicker:"Research",title:"The Same Workflow Results Can Produce Different Rankings",summary:"Across 25 released configurations, partial score and complete acceptance reverse 34 pairwise orderings robustly to rounding. Domain weighting reverses six more, only three beyond rounding uncertainty. State the success objective before interpreting the ranking.",version:"2026-11-11",languageHref:"/zh/industry/2026-11-11-sig-20261111-007",languageLabel:"中文"}),t(n,{language:"en"}),e[0]||(e[0]=c('<h1 id="the-same-workflow-results-can-produce-different-rankings" tabindex="-1">The Same Workflow Results Can Produce Different Rankings <a class="header-anchor" href="#the-same-workflow-results-can-produce-different-rankings" aria-label="Permalink to &quot;The Same Workflow Results Can Produce Different Rankings&quot;">​</a></h1><p>Across 25 released configurations, partial score and complete acceptance reverse 34 pairwise orderings robustly to rounding. Domain weighting reverses six more, only three beyond rounding uncertainty. State the success objective before interpreting the ranking.</p><h2 id="higher-scores-need-not-mean-more-complete-deliveries" tabindex="-1">Higher scores need not mean more complete deliveries <a class="header-anchor" href="#higher-scores-need-not-mean-more-complete-deliveries" aria-label="Permalink to &quot;Higher scores need not mean more complete deliveries&quot;">​</a></h2><p>Two configurations reported by WorkflowArena expose the distinction directly. The high-reasoning setting of Claude Opus 5.5 has a continuous score of 80.21 and complete acceptance of 34.11%; the maximum-reasoning setting scores slightly lower, at 79.94, but completes acceptance more often, at 36.95%. One leads on partial quality, the other on complete acceptance. These are the authors&#39; released aggregates, not model measurements rerun here.</p><p>Continuous scoring preserves information about partially completed work. Complete acceptance asks whether all relevant task conditions were satisfied. The paper&#39;s software-engineering domain even pairs a score of 96.98 with complete acceptance of 17.65%. The two can coexist: a delivery may satisfy most scored items while missing an indispensable condition. Where procurement or deployment requires complete delivery, the continuous score is not a success probability.</p><p>The benchmark contains 145 tasks across eight domains and 17 task forms. Hidden verifiers assess artifacts and applicable process constraints; worker count or topology is not directly rewarded. This article examines interpretation of the same aggregates, rather than inferring that one organization must be better from its leaderboard position.</p><h2 id="compare-the-orderings-pair-by-pair" tabindex="-1">Compare the orderings pair by pair <a class="header-anchor" href="#compare-the-orderings-pair-by-pair" aria-label="Permalink to &quot;Compare the orderings pair by pair&quot;">​</a></h2><p>The same-run internal statistical reanalysis uses only the pinned release already covered by reading: the official repository commit beginning 637adec and paper version 1. It does not merge the later paper version described on the project page. Twenty-five configurations yield 300 unordered pairs. For each pair, opposite nonzero signs for the continuous-score difference and complete-acceptance difference define a strict reversal.</p><p>The completed study records 34 reversals. Analysis then treats every displayed value as rounded to two decimal places, with uncertainty of at most ±0.005. All 34 retain their difference signs under those bounds in both metrics. Metric choice therefore changes the ordering in this table beyond display-rounding ambiguity. The 300 pairs share configurations: 34 reversals are not 34 independent experiments or a statistical-significance result.</p><p>Comparing a metric with itself yields zero reversals as a direction-check control. Reconstructed equal-domain means differ from the released aggregates by at most about 0.005, consistent with displayed rounding. These controls support the aggregation interpretation. They neither validate hidden graders nor turn author results into an independent replication.</p><h2 id="equal-domains-and-equal-tasks-answer-different-questions" tabindex="-1">Equal domains and equal tasks answer different questions <a class="header-anchor" href="#equal-domains-and-equal-tasks-answer-different-questions" aria-label="Permalink to &quot;Equal domains and equal tasks answer different questions&quot;">​</a></h2><p>Released overall acceptance uses an equal-domain mean. The domain counts are 17 software-engineering, 18 operations, 16 science, 24 mathematics, 16 finance, 22 law, 14 content-delivery and 18 3D tasks, totaling 145. Equal-domain averaging gives the 14-task and 24-task domains the same total weight. Task-count weighting gives every task the same nominal weight. Either can be defensible, but they express different objectives.</p><p>The existing internal reanalysis weights the same domain acceptance rates by task counts and finds six strict reversals. Only three remain robust under the rounding-bound check; the other three cannot be described as reliable changes. Task-weighted rates here are approximate reconstructions from rounded domain percentages, not recounts of task-level records.</p><p>Consequently, the best released 36.95% does not mean that 36.95% of all 145 pooled tasks passed. For evaluation engineers, declaring domain importance before ranking configurations is more reviewable than selecting a favorable aggregation after seeing results. We recommend retaining domain-level results alongside the preselected summary. That evaluation-design interpretation does not make task weighting a replacement for the paper&#39;s equal-domain policy.</p><h2 id="transfer-gains-do-not-isolate-topology" tabindex="-1">Transfer gains do not isolate topology <a class="header-anchor" href="#transfer-gains-do-not-isolate-topology" aria-label="Permalink to &quot;Transfer gains do not isolate topology&quot;">​</a></h2><p>The same research compares fixed execution models receiving workflows from different source models. The authors report mean continuous-score gains of +6.4125 and +6.2675 across four executors for Opus-authored static and dynamic settings relative to each executor&#39;s self-dynamic setting. In the existing internal leave-one-executor-out checks, both means stay positive after each omission. The descriptive sign is therefore not driven solely by one executor, but these checks are not repeated trials or confidence intervals.</p><p>Those limits do not negate the potential value of transfer. They constrain attribution: workflows carry organization and instruction knowledge written by the source model. Static programs are frozen before execution, whereas dynamic authors can observe execution and revise. Without separating these factors, score changes cannot be assigned solely to graph structure. Continuous-score gains are also not percentage-point gains in complete acceptance.</p><p>The transfer study uses a purposively harder 32-task subset and only one execution per task. Repeated runs, held-out tasks and controls separating instruction knowledge from organization are needed to assess stability. None was executed in this production task.</p><h2 id="evidence-and-sources-the-reanalysis-boundary" tabindex="-1">Evidence and sources: the reanalysis boundary <a class="header-anchor" href="#evidence-and-sources-the-reanalysis-boundary" aria-label="Permalink to &quot;Evidence and sources: the reanalysis boundary&quot;">​</a></h2><p><a href="https://arxiv.org/html/2611.12856v1" target="_blank" rel="noreferrer">Paper version 1</a> specifies tasks and evaluation protocol. The <a href="https://github.com/Einsia/WorkflowArena/tree/637adecbe59ced8780279301de22b0f582495dea" target="_blank" rel="noreferrer">official pinned repository</a> supplies task data, evaluators and aggregates while explicitly excluding execution frameworks and per-task experimental traces. Both are author primary material; agreement is not outside independent evidence. Internal evidence here means the preceding research stage&#39;s completed aggregate reanalysis and rounding checks. Recommendations are our interpretation.</p><p>One execution per task, missing variance estimates for close rankings, and missing human-agreement measurements for content and 3D semantic judges constrain capability judgments. Thirty-four robust reversals support the claim that metrics change this table&#39;s order, not that a model is truly superior. Three robust weighting reversals establish sensitivity to aggregation policy, not a universally correct weight scheme.</p><p>Publication and citation locate sources without establishing validation or endorsement. Peer review is not proof; self-reported results are not independent evidence; implementation success does not establish general validity. Readers can now check whether their target is partial quality or complete acceptance, freeze domain weights, and demand repeated measurements for close rankings. A single leaderboard place cannot supply certainty missing from the data.</p><p>Internal research material: <a href="/joinwell52/assets/evidence/2026-11-11-sig-20261111-007/wfa-aggregation.json">pairwise reversals, domain weights and transfer sensitivity</a>. <a href="/joinwell52/assets/evidence/2026-11-11-sig-20261111-007/rounding-check.json">Rounding-bound checks</a>. These files preserve completed internal calculations, not an independent replication.</p>',23))])}const b=s(l,[["render",d]]);export{y as __pageData,b as default};
